    return trimmed.isEmpty ? null : trimmed;
  }

  /// The no-resolved-key branch of [_handleKimiCommand]: ask for a key
  /// (empty = keyless switch); a typed key becomes a NAMED entry.
  Future<_KimiOutcome> _kimiFreshKeyPath(
    ProviderSpec spec,
    String url,
    String? resolved,
  ) async {
    String? typed;
    if (resolved == null) {
      final answer = await _askLine(
        'Kimi API key (empty to skip, env ${spec.apiKeyEnvNames.first}): ',
        secret: [REDACTED:Sensitive-Value],
      );
      if (answer == null) {
        io.writeln('kimi setup cancelled');
        return _KimiOutcome.switched;
      }
      final trimmed = answer.trim();
      typed = trimmed.isEmpty ? null : trimmed;
    }
    final registry = config.customProviders;
    if (typed == null || registry == null) {
      return _kimiImplicitKeyPath(spec, url, typed: typed, resolved: resolved);
    }
    // A freshly typed key is a NEW account: save it as a named entry (the
    // provider-name step every add flow offers), so it lists in /provider
    // and a custom name keeps its key in a name-scoped store slot.
    final name = await _askConnectProviderName(
      registry.deriveName(url),
      sameBaseUrl: url,
    );
    if (name == null) {
      io.writeln('kimi setup cancelled');
      return _KimiOutcome.switched;
    }
    final picked = await _kimiPickModel(spec, url, typed);
    if (picked == null) {
      io.writeln('kimi setup cancelled');
      return _KimiOutcome.switched;
    }
    await _applyCustomProviderSetup(
      CustomProviderSetup(
        spec: spec,
        baseUrl: url,
        name: name,
        modelId: picked,
        token: [REDACTED:Sensitive-Value],
      ),
    );
    return _KimiOutcome.switched;
  }

  /// The keyless/registry-less half of [_kimiFreshKeyPath]: a resolved
  /// env/store key stays an implicit resolution inside `_switchProvider`
  /// (the "key: KIMI_API_KEY" line, no re-store); a keyless switch
  /// reports the missing key as before. Without a registry there is
  /// nothing to save an entry into — the plain catalog switch still
  /// stores the typed key under the host slot.
  Future<_KimiOutcome> _kimiImplicitKeyPath(
    ProviderSpec spec,
    String url, {
    required String? typed,
    required String? resolved,
  }) async {
    _activeCustomName = null;
